def minQueriesToZero(nums, queries):
    n = len(nums)

    def ok(k):
        diff = [0] * (n + 1)
        for left, right, cap in queries[:k]:
            diff[left] += cap
            diff[right + 1] -= cap
        run = 0
        for i in range(n):
            run += diff[i]
            if run < nums[i]:
                return False
        return True

    if not ok(len(queries)):
        return -1
    lo, hi = 0, len(queries)
    while lo < hi:
        mid = (lo + hi) // 2
        if ok(mid):
            hi = mid
        else:
            lo = mid + 1
    return lo
